/* Cosmonaut Theme -- "Midnight Desert" Variant

 * [2023 Wikidot Theme]

 * Created by Lt Flops

 * Forked From Cosmonaut Theme by EstrellaYoshte

**/



/* ==== HEADER AREA ==== */

/* == SELECTION == */

 ::selection {

    color: var(--keyColor);

}



/* == COMMON == */

 :root { /* == COLOUR SCHEME == */

    /* DESERT NIGHT */

    --bistre: hsl(309, 36%, 15%);

    --mediumJungleGreen: hsl(240, 27%, 18%);

    --davysGrey: hsl(232, 17%, 35%);

    --desertSand: hsl(25, 63%, 81%);

    --pastelGrey: hsl(21, 35%, 82%);



    /* ARABIAN NIGHT */

    --darkJungleGreen: hsl(235, 36%, 12%);

    --deepCarmine: hsl(341, 81%, 38%);

    --bronze: hsl(34, 59%, 50%);

    --turkishRose: hsl(328, 34%, 53%);

    --indianYellow: hsl(34, 74%, 60%);

    --paleRedViolet: hsl(347, 50%, 64%);



    --bronzeLite: hsla(34, 59%, 50%, .6);

    --paleRedVioletLite: hsla(347, 50%, 74%, .6);

    --davysGreyUltraLite: hsla(232, 17%, 35%, .2);

    --paleRedVioletUltraLite: hsla(347, 50%, 74%, .06);

}



 :root { /* == COLOUR DEFINITIONS == */

    --accentColor: var(--indianYellow);

    --keyColor: black;



    --selectionColor: var(--deepCarmine);

    --headerColor: var(--bronze);



    --maincontentColor: 17, 18, 29;

    --textColor: var(--pastelGrey);



    --darkNightColor: var(--mediumJungleGreen);

    --lightCloudColor: var(--desertSand);

    --hazyCyanColor: var(--bistre);

}



 @font-face { /* == FONT == */

    font-family: "Orthodox Herbertarian";

    src: url(https://cdn.jsdelivr.net/gh/lt-flops/MidnightDesert@main/OrthodoxHerbertarian.woff2) format("woff2");

    font-display: swap;

    font-style: normal;

    font-weight: normal;

}



 :root { /* == OTHER == */

    /* FONT */

    --header-font: "Orthodox Herbertarian", serif;



    /* HOVERTIP */

    --htTrans: .35s;

    --htTransDelay: calc(var(--htTrans) + 1.55s);

}



 #main-content {

    background-color: rgba(var(--maincontentColor), .9);

}



 #main-content::after {

    background-color: var(--indianYellow);

}



 @media (min-width: 768px) {

     #page-content {

     font-size: calc(1rem * 1.05);

    }

}



/* == SITE BANNER == */

 #header h1:focus-within,

 #header h1:hover {

    filter:

       drop-shadow(0px 0px 1.5rem var(--indianYellow))

       brightness(1.75);

}



/* == SIDE-BAR == */

 #side-bar {

    --selectionColor: var(--paleRedViolet);

    --secondOneiroiColor: var(--darkJungleGreen);

}



 #side-bar .heading > p {

    font-size: 110%;

}



/* ==== CONTENT AREA ==== */

/* == BLACKLIGHT BOX == */

 .blbf-main > div,

 .modal {

    margin: 1.5rem auto 2.5rem;



    border-radius: .75rem;

}



 .modal.scpf strong {

    font-variant: small-caps;

}



 .blbf-main > div {

    border-width: thick;



    hyphens: none;

}



 @media (max-width: 767px) {

     .blbf-main > div {

     padding-top: 0;

    }

}



 .blbf-main > div.blbf-dark::before {

    border-radius: .5rem;



    font-variant: small-caps;

}





 .modal {

    width: calc(100% - 3rem);

    padding: 0 .75rem;



    background: var(--paleRedVioletUltraLite);

    border: thick solid var(--bronzeLite);

}



 .modal .logo-wrap {

    width: 100px;

    height: 100px;

    padding: 1rem;

}



/* == BLINKING TEXT CURSOR ==

 * Adapted From:

 *   Word Processor Theme by stormbreath

**/

 .selector {

    animation: blink 1.5s infinite !important;

    color: var(--headerColor);

}

 

 @keyframes blink {

     to {

     opacity: 0;

    }

}



/* == BYLINE == */

 .byline {

    display: flex;

    margin-top: -.33rem;

 

    font-size: 85%;

    text-align: center;

}



 .byline p {

    display: flex;

    flex-direction: column;

    max-width: 50%;

    margin: auto;

 

    line-height: 0;

}



 .byline span:nth-of-type(1):before,

 .byline span:nth-of-type(2):before {

    padding-right: .27rem;

 

    color: var(--accentColor);

 

    font: 135%/1 "Lucida Sans Unicode", "Lucida Grande", "Arial Unicode MS", sans-serif;

}



 .byline span:nth-of-type(1):before {

    content: "✎"

}



 .byline span:nth-of-type(2):before {

    content: "⧗"

}



 .byline span:nth-of-type(2):after {

    content: "-min read"

}



/* == COLLAPSIBLES == */

 .example .collapsible-block-folded,

 .example .collapsible-block-unfolded-link {

    color: var(--selectionColor);

    text-align: center;

}



 .example .collapsible-block-link {

    font-size: 1.55rem;

}



 .licensebox .collapsible-block-link {

    color: var(--paleRedViolet);

}



/* == DIVS == */

 .blockquote.custom {

    width: fit-content;

    margin: 3.5rem auto !important;

    padding: .02rem 1.95rem .02rem 2.95rem;



    font-size: 1.25rem;

    text-align: center;

}



 .fc-news { /* = FOUNDATION NEWS = */

    margin: .65rem;

    padding: .65rem 1rem;



    background-color: var(--firstOneiroiColor);

    border-radius: var(--radius-adjust);

    box-shadow: .05rem .1rem .45rem var(--shadow);

    box-sizing: border-box;

}



 .fc-news > span:first-child {

    display: flex;

    align-items: center;



    --headerColor: var(--indianYellow);

    color: var(--paleRedViolet);



    font: bold 1.1em var(--body-font);

}



 .fc-news :where(img) {

    width: 5%;

    margin-right: .5rem;

    filter: invert(63%) sepia(22%) saturate(1145%) hue-rotate(301deg) brightness(87%) contrast(86%);

}



 .cloudbox::before {

    bottom: 100%;

}





/* == ENLARGE == */

 .enlarge {

    position: relative;

    transition: .25s;

    z-index: 1000;

}



 .enlarge:hover {

    transform: scale(2);

    transition: .25s;

}



/* == FADE AWAY == */

 #u-fade-away {

    /* Mouse Hover Reveals Rating Module */

    opacity: calc(1 / 3);

    transition: all .25s ease-in-out;

}



 #u-fade-away:hover {

    opacity: 1;

}



/* == FLOPS HEADER PATCH == */

 .darkbox {

    margin: 1rem 0;

    padding: .4rem .6rem;



    color: var(--accentColor);

    background: var(--davysGreyUltraLite);

    border-right: 7px solid var(--headerColor);

    border-left: 7px solid var(--headerColor);

}



 .itemInfo.darkbox {

    margin: 0 0 1.6rem;

    padding: .8rem 1.13rem;



    color: var(--textColor);

}



 table.darkbox tr td {

    padding: 0;

}



 .alignL span {

    margin-right: .13rem;

}



 .infofield_1, .infofield_2 {

    font-size: 0;

}



 .infofield_1::before {

    content: "ITEM #";

}



 .infofield_2::before {

    content: "CLASS";

}



 .itemInfoHeading {

    white-space: normal;

}



 @media (max-width: 767.9px) {

     .itemInfo.darkbox,

     .infofield_1::before,

     .infofield_2::before,

     .infofield_3::before,

     #page-content a.disruptionHeader {

     font-size: .95rem;

    }



     .itemInfo.darkbox {

     margin: 0 0 1.25rem;

     padding: 0 .75rem;

    }



     .infofield_3 {

     font-size: 0;

    }



     .infofield_3::before {

     content: "LVL";

    }

}



 @media (min-width: 768px) {

     .itemInfo tr:nth-child(2) td:nth-child(2) span,

     .itemInfoHeading,

     .infofield_1::before,

     .infofield_2::before {

     font-size: 1.25rem;

    }

}



/* == FOOTING == */

 .footing, .footing:after {

    position: relative;

}

 

 .footing {

    margin: 1rem 0;

    padding-top: 1.6rem;

}

 

 .footing::before {

    position: absolute;

    right: 0;

    bottom: .27rem;

    left: 0;

    content: "";

 

    border-bottom: 4px solid var(--paleRedViolet);

}

 

 .footing:after {

    display: block;

    top: .13rem;

    content: "";

 

    border-bottom: 2px solid var(--paleRedVioletLite);

}

 

 @media (max-width: 767px) {

     .footing::before, .footing:after {

     margin: 0 -5%;

    }

}



/* == FOOTNOTES == */

 a.footnoteref {

    --accentColor: var(--bronze);

    font-size: .95rem;

    font-weight: bold;

}



 a.footnoteref:hover {

    --accentColor: var(--indianYellow);

    text-decoration: none;

}



 .hovertip {

    transition-duration: var(--htTrans);

    transition-delay: var(--htTransDelay);

}



/* == FORMATTING | [GENERAL] == */

 h1, h2, h3, h4, h5, h6,

 #side-bar .heading > p {

    font-weight: normal;

    font-variant: small-caps;

    text-rendering: geometricPrecision;

    word-break: normal;

}



 h1, h2, h3, h4, h5, h6 {

    color: var(--indianYellow);

}



 #page-title {

    display: none;

}



 .meta-title {

    color: var(--indianYellow);

    font-size: 3em;

}



 hr, .or-card::before {

    --accentColor: var(--paleRedViolet);

    --headerColor: var(--davysGrey);

}



/* == FORMATTING | [SPECIAL] == */

 .bt {   /* Bold-Text = Bold + accentColor */

    color: var(--accentColor);



    font-weight: bold;

    text-decoration-color: inherit;

}



 .bt.bb {   /* Big-Bar = Bold + accentColor + Vertical Bar [Body Text] */

    border-right: medium solid var(--accentColor);

}



 .bt.bb::after {

    content: ":";

    visibility: hidden;

}



 .itemInfoHeading,

 .luna,

 strong {

    color: var(--headerColor);

}



 .invalid {

    display: flex;

    align-items: center;

    justify-content: center;

    margin: auto;

    padding: 1rem 0;



    color: var(--deepCarmine);

    filter: brightness(1.5);



    font: bold 1.25rem var(--mono-font);

    text-align: center;

}



 .invalid::before,

 .invalid::after {

    font: 5rem var(--mono-font);

}



 .invalid::before {

    content: "[";

}



 .invalid::after {

    content: "]";

}



 .lite-heading h1 {

    color: var(--paleRedViolet);

}



 .lite-heading hr:first-child {

    margin-top: 5rem;

    margin-bottom: -1rem;

    background:

      linear-gradient(180deg,

     var(--headerColor),

     var(--accentColor));

}



 .lite-heading hr:last-child {

    margin-top: -1rem;

    margin-bottom: 5rem;

}



 .loader {

    width: 325px;



    filter: brightness(.8) drop-shadow(0 0 4px black) opacity(.8) sepia(.4);

}



 .logo-wrap {

    width: 65%;

    filter: invert(73%) sepia(15%) saturate(2484%) hue-rotate(339deg) brightness(86%) contrast(82%);

}



 @media (min-width: 768px) {

     .logo-wrap {

     width: 50%;

    }



     h1 { font-size: 2rem; }

     h2 { font-size: 1.6rem; }

     h3 { font-size: 1.4rem; }

     h4 { font-size: 1.3rem; }

     h5 { font-size: 1.2rem; }

     h6 { font-size: 1.1rem; }

}



 .page-source {

    word-break: unset;

}



 .page-source.prompt {

    font: 1.05rem var(--mono-font);

    text-align: center;

}



 .pseudo-heading {

    font-family: var(--header-font);

}



 .scp-header {

    font-size: xx-large;

    text-underline-offset: 25%;

}



 .text-fade {

    -webkit-mask-image:

       linear-gradient(

     transparent,

     rgb(0,0,0,.5) 30%,

     rgb(0,0,0,1) 45%,

     rgb(0,0,0,1) 55%,

     rgb(0,0,0,.5) 70%,

     transparent);

}



/* == INFO BAR == */

 .info-container {

    --barColour: var(--darkNightColor);

    --linkColour: var(--indianYellow);

}



 #u-author_block { display:none; }



/* == SOCIAL MEDIA EFFECTS == */

 .or-footer > p span:last-child a,

 .or-tweet > ul li {

    color: var(--turkishRose);

}



 .or-tweet > span:first-child {

    color: hsl(355, 11%, 58%);



    font-size: .75em;

}



 .or-tweet > span:first-child img {

    position: relative;

    top: .4rem;

    max-width: 24px;

    padding-top: 1.6rem;

}



/* == TIMELINE == */

.timeline {

    padding-top: 24px;

    padding-bottom: 24px;



    background: var(--paleRedVioletUltraLite);

    border-left: 8px solid var(--headerColor);

    border-radius: 16px;

}



 #page-content .page-source::before {

    --bq-edge-mask: none;

}



 .timeline .page-source::after {

    position: absolute;

    top: -14px;

    left: -16px;

    width: 24px;

    height: calc(100% + 28px);

    content: "";



    background: hsl(34, 59%, 37.5%);

    border-radius: 0 16px 16px 0;

}



/* == YUI TABS == */

 .yui-navset .yui-nav .selected a {

    color: var(--bistre);

}



/* ==== PAGE OPTIONS CONTAINER ==== */

/* == EDIT PAGE | [TEXT AREA] == */

 #edit-page-textarea {

    width: 100%;



    color: var(--lightCloudColor);

    background: var(--darkNightColor);



    font: 1.05rem var(--body-font);

}



 .inline-diff del,

 .inline-diff ins {

    color: var(--keyColor);

}



 .hazard {

  font-weight: bold;

    color: #c92f2f;

}

[[/module]]
